  steps:["Επικοινωνία της τράπεζας για την καθυστέρηση (ή αίτημά σου).","Υποβολή ΤΟΚ και στοιχείων – χαρακτηρισμός ως «συνεργάσιμος».","Αξιολόγηση και πρόταση λύσης.","Αποδοχή ή αιτιολογημένη απόρριψη – δικαίωμα ένστασης/προσφυγής."],
