  who:"Φυσικά πρόσωπα και επιχειρήσεις με συνολικές οφειλές από 5.000€ (Ν.5313/2026, ενδεικτικά – έλεγξε το τρέχον όριο).",
  docs:["Κωδικοί TaxisNet (δικοί σου, συζύγου, συνοφειλετών, εγγυητών)","Άρση τραπεζικού απορρήτου – συναινέσεις","Στοιχεία εισοδήματος, περιουσίας, οφειλών (αντλούνται κυρίως αυτόματα)"],
