  cost:"Ενδεικτικά μικρό αντίτιμο/τέλος ανά ποσότητα.",
  time:"Αιτήσεις συνήθως σε ορισμένη περίοδο κάθε έτους· έκδοση ενδεικτικά σε λίγες εβδομάδες.",
  channels:["kep","ypiresia"], auth:"Όχι",
