  steps:["Ανάθεσε σε τοπογράφο τη σύνταξη διαγράμματος","Έλεγξε αν επηρεάζονται όμορα ακίνητα","Υπόβαλε αίτηση (υπηρεσία metavoles / Κτηματολογικό Γραφείο)","Πλήρωσε το τέλος","Απόφαση Προϊσταμένου & ενημέρωση διαγράμματος"],
