  steps:["Σύνταξη αίτησης (ιδανικά με δικηγόρο)","Κατάθεση στο Υπουργείο Δικαιοσύνης","Γνωμοδότηση Συμβουλίου Χαρίτων","Πρόταση Υπουργού","Προεδρικό Διάταγμα (αν εγκριθεί)"],
