  auth:"Κωδικοί εφαρμογής παρόχου (π.χ. myΔΕΗ)",
  url:"https://www.deddie.gr/en/services/metering-service/",
  steps:["Εξοφλήστε ή ρυθμίστε την οφειλή με τον πάροχό σας","Ζητήστε από τον πάροχο εντολή επανασύνδεσης","Ο ΔΕΔΔΗΕ εκτελεί την επανασύνδεση","Για κενό ακίνητο: αίτηση λύσης σύμβασης στον πάροχο (ζητήστε καταμέτρηση)"],
