  cost:"Τέλος σύνδεσης ανά κατηγορία (ενδεικτικά μερικές εκατοντάδες €) + κόστος εσωτερικής εγκατάστασης· συχνά υπάρχουν προσφορές δωρεάν σύνδεσης.",
  time:"Ενδεικτικά 1–3 μήνες.",
  channels:["online","ypiresia"],
  auth:"Φόρμα αίτησης στο ena-on.com",
  url:"https://www.ena-on.com/en/apply-for-new-connection/",
  steps:["Ελέγξτε αν υπάρχει δίκτυο στον χάρτη της Enaon EDA","Υποβάλετε αίτηση σύνδεσης για την περιοχή σας","Υπογράψτε σύμβαση σύνδεσης & πληρώστε το τέλος","Κατασκευή παροχής από τον Διαχειριστή","Εσωτερική εγκατάσταση από αδειούχο – έλεγχος/ενεργοποίηση","Σύμβαση με προμηθευτή φυσικού αερίου"],
