  cost:"ΕΥΔΑΠ: προκαταβολή «Δαπάνη Έρευνας» 63,12 € ανά κοινή παροχή (168,53 € για ειδική)· συνολικό κόστος κοινής παροχής ενδεικτικά ~606 €. ΔΕΥΑ: βάσει δικού τους τιμολογίου.",
