  docs:["Αίτηση καταγγελίας","Αντίγραφο ταυτότητας ή διαβατηρίου"],
  cost:"Χωρίς χρέωση σε αορίστου χρόνου/καρτοκινητή· σε ορισμένου χρόνου βάσει του τύπου της ΕΕΤΤ (ενδεικτικά).",
  time:"Διακοπή εντός 2 εργάσιμων (κινητή) / 8 εργάσιμων (σταθερή) εκτός αν ζητήσετε συγκεκριμένη ημερομηνία.",
  channels:["online","ypiresia"],
