  steps:["Υποβάλετε γραπτή καταγγελία με αντίγραφο ταυτότητας","Κρατήστε αριθμό πρωτοκόλλου/επιβεβαίωση","Επιστρέψτε εξοπλισμό αν απαιτείται","Ελέγξτε ότι ο τελικός λογαριασμός τηρεί τον τύπο της ΕΕΤΤ"],
