  steps:["Επανεκκινήστε router και ελέγξτε καλώδια","Δηλώστε τη βλάβη στον πάροχο (Cosmote 13888, Vodafone 13830, Nova 13831 ή app)","Κρατήστε τον αριθμό βλάβης","Ζητήστε προσωρινή εκτροπή κλήσεων αν χρειάζεται","Ελέγξτε ότι πιστώθηκε το πάγιο· αλλιώς παράπονο στον πάροχο και στην ΕΕΤΤ"],
